idx.write_text(s,encoding='utf-8')

# add preconnect hints and lazy loading broadly
for f in ROOT.rglob('*.html'):
    txt=f.read_text(encoding='utf-8',errors='ignore')
    if 'cdn.tailwindcss.com' in txt and 'preconnect' not in txt:
        txt=txt.replace('<script src="https://cdn.tailwindcss.com"></script>','<link rel="preconnect" href="https://cdn.tailwindcss.com"><link rel="preconnect" href="https://cdnjs.cloudflare.com"><script src="https://cdn.tailwindcss.com"></script>')
    txt=txt.replace('<img ', '<img loading="lazy" decoding="async" ')
    f.write_text(txt,encoding='utf-8')

# remove any visible NEW badges from audio / all tool pages
for f in (ROOT/'herramientas').glob('*/index.html'):
    txt=f.read_text(encoding='utf-8',errors='ignore')
    txt=re.sub(r'<[^>]*>\s*(?:NUEVO|Nuevo|NEW)\s*</[^>]+>','',txt,flags=re.I)
    f.write_text(txt,encoding='utf-8')

# quick syntax checks by node
PYTHON=__import__('subprocess')
for js in [AS/'tool.js',AS/'enhance.js']:
    r=PYTHON.run(['node','--check',str(js)],capture_output=True,text=True)
    if r.returncode: raise SystemExit(f'JS syntax error {js}: {r.stderr}')
